def stored_characters() -> dict[int, Character]:
    """start.gg's characters by id, the same Characters `videogame_characters()` returns

    `char_group` and `char_icon` are worked out from the name on each call, so a fix to the
    name matching (or a roster change) applies without a refresh.
    """
    return {
        character_id: startgg_character(character_id, name) for character_id, name in STARTGG_CHARACTER_NAMES.items()
    }


def _source(characters: dict[int, Character]) -> str:
    """The generated part of this file for `videogame_characters()`' result"""
    # json.dumps: double quotes, as ruff-format writes strings (else they rewrite each other)
    rows = [f"    {c.id}: {json.dumps(c.name)}," for c in sorted(characters.values(), key=lambda c: c.id)]
    return "\n".join([_BEGIN, "STARTGG_CHARACTER_NAMES: dict[int, str] = {", *rows, "}", _END])


def write_startgg_characters(characters: dict[int, Character], module: Path = Path(__file__)) -> bool:
    """Rewrite this file's generated dict from `videogame_characters()`; True if changed"""
    source = module.read_text()
    # at a line's start: the markers' own definitions above aren't the block
    start = source.index("\n" + _BEGIN) + 1
    end = source.index("\n" + _END) + 1 + len(_END)
    updated = source[:start] + _source(characters) + source[end:]
    if updated == source:
        return False
    module.write_text(updated)
    return True
